internal static class AuraAnimationGuiTests {
 static int checks,layouts;
 const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool condition,string name){checks++;if(!condition)throw new Exception(name);}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static object Invoke(MainWindow window,string name,params object[] args){var method=typeof(MainWindow).GetMethod(name,Hidden|BindingFlags.Public);if(method==null)throw new MissingMethodException(name);return method.Invoke(window,args);}
 static IEnumerable<T> Logical<T>(DependencyObject root)where T:DependencyObject {if(root is T)yield return (T)root;foreach(var item in LogicalTreeHelper.GetChildren(root)){var child=item as DependencyObject;if(child!=null)foreach(var value in Logical<T>(child))yield return value;}}
 static T Tag<T>(DependencyObject root,string tag)where T:FrameworkElement{return Logical<T>(root).Single(c=>Object.Equals(c.Tag,tag));}
 static void NoIo(MainWindow window){Check(!window.IsVisible&&new WindowInteropHelper(window).Handle==IntPtr.Zero&&PresentationSource.FromVisual(window)==null,"no native HWND or shown window");foreach(var field in typeof(MainWindow).GetFields(Hidden).Where(f=>f.FieldType==typeof(WorkerClient))){var worker=(WorkerClient)field.GetValue(window);Check(worker==null||typeof(WorkerClient).GetField("process",Hidden).GetValue(worker)==null,"no worker: "+field.Name);}Check(((Dictionary<string,WorkerClient>)Field(window,"sdkWorkers")).Count==0,"no SDK worker client");}
 static void Faults(MainWindow window,string method,params object[] args){bool rejected=false;try{var task=Invoke(window,method,args) as Task;if(task!=null)task.GetAwaiter().GetResult();}catch(Exception){rejected=true;}Check(rejected,"invalid binding or policy rejects before transport: "+method);}
 static void Views(){var window=new MainWindow(true);Check(!((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).Enabled,"default hardware permission is disabled");foreach(double width in new[]{1180.0,1538.0})foreach(string effect in new[]{"static","breathe","cycle","flash","off"}){Set(window,"effect",effect);Set(window,"auraTab","Aura 灯效");Invoke(window,"ShowPage","灯效 & Aura Sync");var frame=(FrameworkElement)window.Content;frame.Measure(new Size(width,826));frame.Arrange(new Rect(0,0,width,826));frame.UpdateLayout();layouts++;Check(frame.ActualWidth==width&&frame.ActualHeight==826,"unshown layout has requested geometry");foreach(string supported in new[]{"static","breathe","cycle","flash","off"})Check(Tag<Button>(frame,"aura-effect:"+supported).IsEnabled,"verified uniform effect is a local draft option");foreach(string unsupported in new[]{"rainbow","stars","music","smart","adaptive","immersive","ai"}){var button=Tag<Button>(frame,"aura-effect:"+unsupported);Check(!button.IsEnabled&&button.ToolTip!=null,"unsupported feature remains disabled with reason");}Check(!Tag<Button>(frame,"aura-apply").IsEnabled,"render/default-off cannot start animation");var level=Tag<Slider>(frame,"aura-brightness");level.Value=0;Check((int)Field(window,"brightness")==0,"zero brightness is preserved as a local draft");if(AuraAnimationPhase.SupportsUniform(effect)){var period=Tag<ComboBox>(frame,"aura-period");period.SelectedIndex=0;Check((double)Field(window,"auraAnimationPeriodSeconds")==12,"period combo modifies local draft only");}Check(!window.AuraAnimationActive&&window.AuraAnimationCanPreviewReload,"layout and draft editing never auto-start animation");NoIo(window);}
  Set(window,"render",false);Invoke(window,"ApplyAllAuraTargetsAsync");Check(!window.AuraAnimationActive&&!(bool)Field(window,"busy"),"default-off apply callback starts no scheduler");NoIo(window);Set(window,"render",true);
 }
 static void Lifecycle(){var window=new MainWindow(true);Set(window,"render",false);int writes=0;var state=new Dictionary<string,object>{{"id","native-pure"},{"backend","native-hid"},{"vendorId","0B05"},{"productId","1AA6"},{"controllerFamily","motherboard"},{"zoneCount",1},{"leds",1},{"effects",new[]{"static"}}};var target=AuraSyncCoordinator.Direct(state,"Synthetic",DateTime.UtcNow);var session=new object();target.WorkerSession=session;var binding=new AuraAnimationBinding{Target=target,WorkerSession=session};var controller=new AuraAnimationController(()=>0,(ms,token)=>Task.FromResult(0));Check(controller.PrepareAsync(new[]{binding},new AuraAnimationOptions(),b=>Task.FromResult(b),c=>{writes++;return Task.FromResult(new AuraSyncCommandReply{Ok=true});},()=>{},b=>true).GetAwaiter().GetResult(),"pure scheduler prepared without worker");Set(window,"auraAnimation",controller);var pending=new TaskCompletionSource<bool>();Set(window,"auraAnimationTask",pending.Task);Set(window,"auraSyncConnectionsActive",true);Set(window,"controlling",true);((Dictionary<string,object>)Field(window,"gearReadSessions"))["mouse"]=session;Check(window.AuraSyncBusy&&!window.AuraAnimationCanPreviewReload,"active loop blocks preview replacement");Invoke(window,"OnAuraAnimationNavigation","device:mouse");var stopping=(Task)Field(window,"auraStopTask");Check(stopping!=null&&!stopping.IsCompleted&&writes==0,"navigation stop waits tracked request lifetime");Check(((Dictionary<string,object>)Field(window,"gearReadSessions")).Count==0&&!(bool)Field(window,"busy"),"navigation invalidates bindings without granting global busy");Check(window.AuraSyncBusy&&!window.AuraAnimationCanPreviewReload,"stop transaction remains busy until owned task finishes");var waiting=(Task)Invoke(window,"WaitAuraAnimationAsync",false);Check(!waiting.IsCompleted,"closing/lifecycle wait joins existing navigation transaction");pending.SetResult(true);stopping.GetAwaiter().GetResult();waiting.GetAwaiter().GetResult();Check(!window.AuraSyncBusy&&window.AuraAnimationCanPreviewReload&&!window.AuraSyncConnectionsActive&&writes==0,"idle is reported only after tracked stop completes");NoIo(window);
  var expired=new AuraOwnershipResult{Target=target,WorkerSession=new object(),OwnershipConfirmed=true,CanReturnOriginalFlag=true};((Dictionary<string,AuraOwnershipResult>)Field(window,"auraOwnershipResults"))[target.Id]=expired;((Task)Invoke(window,"ReturnConfirmedAuraOwnership")).GetAwaiter().GetResult();Check(expired.RestorationState=="connectionExpired"&&!expired.RestorationConfirmed,"cached/other-worker receipt cannot restore hardware ownership");NoIo(window);
  var command=AuraSyncCoordinator.BuildStaticCommands(target,"#123456")[0];Faults(window,"SendAuraSyncCommand",command);((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(true);Faults(window,"SendAuraSyncCommand",command);Faults(window,"RefreshAuraSyncTarget",target);Check(writes==0,"invalid original session never falls back to worker restart");Set(window,"closing",true);Faults(window,"SendAuraSyncCommand",command);Check(!window.AuraAnimationActive,"closing cannot revive software animation");NoIo(window);
 }
  static string Status(MainWindow window){var panel=new StackPanel();Invoke(window,"OriginalAuraOperationStatus",panel);return Tag<TextBlock>(panel,"aura-operation-status").Text;}
  static void HonestLightingStatus(){
   var window=new MainWindow(true);Set(window,"render",false);Set(window,"auraTab","Aura 灯效");
   var target=new AuraSyncTarget{Id="direct:synthetic-status",DeviceId="synthetic-status",Backend="direct",Kind="motherboard",Name="Synthetic board",Online=true,CanStaticRgb=true,PhysicalWriteValidated=false};
   var targets=(List<AuraSyncTarget>)Field(window,"auraSyncTargets");var selected=(HashSet<string>)Field(window,"auraSyncSelected");targets.Add(target);selected.Add(target.Id);
   Invoke(window,"ShowPage","灯效 & Aura Sync");var frame=(FrameworkElement)window.Content;var apply=Tag<Button>(frame,"aura-apply");Check(!apply.IsEnabled&&Convert.ToString(apply.ToolTip)==HardwareControlPolicy.BlockedMessage&&ToolTipService.GetShowOnDisabled(apply),"default-off Apply explains the real permission gate");
   ((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(true);Invoke(window,"ShowPage","灯效 & Aura Sync");apply=Tag<Button>((FrameworkElement)window.Content,"aura-apply");Check(!apply.IsEnabled&&Convert.ToString(apply.ToolTip).Contains("本次连接"),"cached/prepared targets without a live worker cannot enable Apply");
   selected.Clear();Invoke(window,"ShowPage","灯效 & Aura Sync");apply=Tag<Button>((FrameworkElement)window.Content,"aura-apply");Check(!apply.IsEnabled&&Convert.ToString(apply.ToolTip).Contains("勾选"),"no selection explains its own disabled Apply reason");
   Set(window,"busy",true);Check(Convert.ToString(Invoke(window,"AuraApplyUnavailableReason")).Contains("请求尚未结束"),"pending operation is distinguished from missing permission");Set(window,"busy",false);Set(window,"closing",true);Check(Convert.ToString(Invoke(window,"AuraApplyUnavailableReason")).Contains("结束设备连接"),"closing explains its own gate");Set(window,"closing",false);Set(window,"render",true);Check(Convert.ToString(Invoke(window,"AuraApplyUnavailableReason")).Contains("仅展示布局"),"render-only never masquerades as normal writable preview");Set(window,"render",false);
   Set(window,"auraTab","同步设备");Invoke(window,"ShowPage","灯效 & Aura Sync");frame=(FrameworkElement)window.Content;Check(Tag<TextBlock>(frame,"aura-target-state:"+target.Id).Text=="待读取","old capability without current worker session is visibly stale");target.WorkerSession=new object();Invoke(window,"ShowPage","灯效 & Aura Sync");frame=(FrameworkElement)window.Content;var state=Tag<TextBlock>(frame,"aura-target-state:"+target.Id);Check(state.Text=="待验证"&&Convert.ToString(state.ToolTip).Contains("尚未完成"),"prepared route does not claim a validated hardware write");Check(Logical<CheckBox>(frame).Any(c=>c.IsEnabled&&Convert.ToString(c.ToolTip).Contains("只选择设备")),"selection is described as a draft rather than an instant device write");
   target.PhysicalWriteValidated=true;Invoke(window,"ShowPage","灯效 & Aura Sync");Check(Tag<TextBlock>((FrameworkElement)window.Content,"aura-target-state:"+target.Id).Text=="可同步","explicit physical-validation fact is retained");target.PhysicalWriteValidated=false;
   Set(window,"auraSyncResult",new AuraSyncResult{Devices=new[]{new AuraSyncTargetResult{TargetId=target.Id,ReadbackConfirmed=true,State="readbackConfirmed"}}});Invoke(window,"ShowPage","灯效 & Aura Sync");Check(Tag<TextBlock>((FrameworkElement)window.Content,"aura-target-state:"+target.Id).Text=="配置已读回","real configuration readback remains visible independently of visual verification");Set(window,"auraSyncResult",null);
   target.CanStaticRgb=false;target.CanReleaseSoftwareLighting=true;((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(false);Invoke(window,"ShowPage","灯效 & Aura Sync");var take=Tag<Button>((FrameworkElement)window.Content,"aura-take:"+target.Id);Check(!take.IsEnabled&&Convert.ToString(take.ToolTip)==HardwareControlPolicy.BlockedMessage&&ToolTipService.GetShowOnDisabled(take),"ownership button explains default-off permission without changing it");
   ((Dictionary<string,AuraOwnershipResult>)Field(window,"auraOwnershipResults"))[target.Id]=new AuraOwnershipResult{Target=target,CanReturnOriginalFlag=true,OwnershipConfirmed=true};Invoke(window,"ShowPage","灯效 & Aura Sync");var give=Tag<Button>((FrameworkElement)window.Content,"aura-return:"+target.Id);Check(!give.IsEnabled&&Convert.ToString(give.ToolTip)==HardwareControlPolicy.BlockedMessage&&ToolTipService.GetShowOnDisabled(give),"return button cannot silently bypass the same policy");NoIo(window);
   var session=new object();var binding=new AuraAnimationBinding{Target=new AuraSyncTarget{Id="direct:synthetic-frame",DeviceId="synthetic-frame",Backend="direct",Kind="motherboard",Online=true,CanStaticRgb=true,State=new Dictionary<string,object>{{"id","synthetic-frame"},{"backend","native-hid"},{"vendorId","0B05"},{"productId","1AA6"},{"controllerFamily","motherboard"},{"zoneCount",1},{"leds",1},{"effects",new[]{"static"}}}},WorkerSession=session};binding.Target.WorkerSession=session;
   int sends=0;var read=new TaskCompletionSource<AuraAnimationBinding>();var response=new TaskCompletionSource<AuraSyncCommandReply>();var controller=new AuraAnimationController(()=>0,(ms,token)=>Task.FromResult(0));var preparation=controller.PrepareAsync(new[]{binding},new AuraAnimationOptions(),b=>read.Task,c=>{sends++;return response.Task;},()=>{},b=>true);Set(window,"auraAnimation",controller);Set(window,"auraSyncMessage","Synthetic status");Check(Status(window)=="正在核对灯光…"&&sends==0,"preflight with no output cannot be shown as running");read.SetResult(binding);Check(preparation.GetAwaiter().GetResult(),"fake preflight completes");Check(Status(window)=="等待首帧结果…"&&controller.Report.Frames==0&&sends==0,"prepared zero-frame animation is visibly unconfirmed");
   var first=controller.TickAsync();Check(!first.IsCompleted&&Status(window)=="等待首帧结果…"&&sends==1,"in-flight first submission is not a completed frame");response.SetResult(new AuraSyncCommandReply{Ok=true,Accepted=true,WriteAttempted=true,WriteConfirmed=false});first.GetAwaiter().GetResult();Check(Status(window)=="软件同步运行中 · 灯光读回未确认"&&controller.Report.Frames==1,"direct output without readback remains explicitly unconfirmed");controller.Report.AllLastFrameReadbackConfirmed=true;Check(Status(window)=="软件同步运行中 · 配置已读回","confirmation requires the completed report flag");controller.Report.State="faulted";Set(window,"auraAnimationTask",new TaskCompletionSource<bool>().Task);Check(Status(window)=="同步已停止","pending task cleanup after a failure is not displayed as running");Check(sends==1,"all status and permission interactions used only one fake callback and no actual writes");NoIo(window);
  }
  static void FirstFrameLifetime(){
   var state=new Dictionary<string,object>{{"id","synthetic-first"},{"backend","native-hid"},{"vendorId","0B05"},{"productId","1AA6"},{"controllerFamily","motherboard"},{"zoneCount",1},{"leds",1},{"effects",new[]{"static"}}};var target=AuraSyncCoordinator.Direct(state,"Synthetic",DateTime.UtcNow);var session=new object();target.WorkerSession=session;var binding=new AuraAnimationBinding{Target=target,WorkerSession=session};
   foreach(bool rejected in new[]{true,false}){
    var window=new MainWindow(true);int sends=0,pauses=0;AuraAnimationController controller=null;
    controller=new AuraAnimationController(()=>0,(ms,token)=>{pauses++;controller.RequestStop();return Task.FromResult(0);});
    Check(controller.PrepareAsync(new[]{binding},new AuraAnimationOptions(),b=>Task.FromResult(b),c=>{sends++;return Task.FromResult(new AuraSyncCommandReply{Ok=!rejected,WriteAttempted=true,WriteConfirmed=false,Error=rejected?"Synthetic rejected first frame":null});},()=>{},b=>true).GetAwaiter().GetResult(),"fake first-frame preflight completes");
    Set(window,"auraAnimation",controller);((Task)Invoke(window,"RunAuraAnimationLifetimeAsync")).GetAwaiter().GetResult();
    Check(sends==1,"tracked lifetime never repeats its first output at the same phase");
    if(rejected){Check(pauses==0&&controller.Report.Frames==0&&controller.Report.State=="faulted","first-frame failure cannot enter RunAsync or clear fault evidence");Check(Convert.ToString(Field(window,"auraSyncMessage")).Contains("Synthetic rejected"),"first-frame error remains visible rather than running success");}
    else{Check(pauses==1&&controller.Report.Frames==1&&!controller.Report.AllLastFrameReadbackConfirmed,"first direct frame stays unconfirmed and nextDue suppresses a duplicate");Check(Convert.ToString(Field(window,"auraSyncMessage")).Contains("仍需确认"),"stopped output does not claim hardware effect confirmation");}
    NoIo(window);
   }
  }
  static void RestoredLightingIsNotLive(){
   var origin=new MainWindow(true);Set(origin,"page","灯效 & Aura Sync");Set(origin,"auraTab","同步设备");
   var target=new AuraSyncTarget{Id="gear:mouse:synthetic-resume",DeviceId="synthetic-resume",Backend="gear",Kind="mouse",Name="Synthetic mouse",Online=true,CanStaticRgb=true,CanReleaseSoftwareLighting=true,PhysicalWriteValidated=true,WorkerSession=new object()};
   ((List<AuraSyncTarget>)Field(origin,"auraSyncTargets")).Add(target);((HashSet<string>)Field(origin,"auraSyncSelected")).Add(target.Id);
   Set(origin,"auraSyncResult",new AuraSyncResult{AllSubmitted=true,AllReadbackConfirmed=true,Devices=new[]{new AuraSyncTargetResult{TargetId=target.Id,ReadbackConfirmed=true,WriteAttempted=true,State="readbackConfirmed"}}});
   ((Dictionary<string,AuraOwnershipResult>)Field(origin,"auraOwnershipResults"))[target.Id]=new AuraOwnershipResult{Target=target,WorkerSession=target.WorkerSession,OwnershipConfirmed=true,CanReturnOriginalFlag=true,WriteAttempted=true};
   var oldAttempts=(Dictionary<string,DateTime>)Field(origin,"pageReadAttempts");oldAttempts["灯效 & Aura Sync"]=DateTime.UtcNow;oldAttempts["神光同步"]=DateTime.UtcNow;oldAttempts["设备兼容"]=DateTime.UtcNow;
   ((HardwareControlPolicy)Field(origin,"hardwareControlPolicy")).SetEnabled(true);var restored=new MainWindow(true);restored.RestorePreviewState(origin.CapturePreviewState());
   var rows=(List<AuraSyncTarget>)Field(restored,"auraSyncTargets");Check(rows.Count==1&&rows[0].WorkerSession==null&&!rows[0].CanStaticRgb&&!rows[0].CanReleaseSoftwareLighting&&!rows[0].PhysicalWriteValidated,"restored saved capability is retired rather than declared live");
   Check(((HashSet<string>)Field(restored,"auraSyncSelected")).SetEquals(new[]{target.Id}),"selected device IDs survive solely as a view draft");
   Check(Field(restored,"auraSyncResult")==null&&((Dictionary<string,AuraOwnershipResult>)Field(restored,"auraOwnershipResults")).Count==0,"old success and ownership receipts cannot cross a new worker session");
   Check(!restored.PreviewHardwareWritesEnabled&&!restored.AuraSyncConnectionsActive,"restoration grants neither permission nor a live connection");
   var attempts=(Dictionary<string,DateTime>)Field(restored,"pageReadAttempts");Check(!attempts.ContainsKey("灯效 & Aura Sync")&&!attempts.ContainsKey("神光同步")&&attempts.ContainsKey("设备兼容"),"new Aura read is not suppressed by the old throttle while unrelated keys remain");
   Invoke(restored,"ShowPage","灯效 & Aura Sync");Check(Tag<TextBlock>((FrameworkElement)restored.Content,"aura-target-state:"+target.Id).Text=="待读取","restored card cannot display old writable or success status");
   Set(restored,"render",false);((HardwareControlPolicy)Field(restored,"hardwareControlPolicy")).SetEnabled(true);Set(restored,"auraTab","Aura 灯效");Invoke(restored,"ShowPage","灯效 & Aura Sync");var apply=Tag<Button>((FrameworkElement)restored.Content,"aura-apply");Check(!apply.IsEnabled&&Convert.ToString(apply.ToolTip).Contains("本次连接"),"explicitly enabled policy still cannot write using restored IDs alone");
   Invoke(restored,"QueuePageRead","灯效 & Aura Sync");Check(Convert.ToString(Field(restored,"pendingPageRead"))=="灯效 & Aura Sync"&&Field(restored,"pageReadTimer")==null,"a fresh read may queue without pumping a timer or touching hardware");NoIo(origin);NoIo(restored);
  }
  [STAThread]static int Main(){try{Views();Lifecycle();HonestLightingStatus();FirstFrameLifetime();RestoredLightingIsNotLive();Console.WriteLine("Aura animation GUI: "+checks+" pure checks, "+layouts+" unshown layouts; HWND 0, worker requests 0, hardware writes 0.");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
